/**
 * Aplana el payload de Meta a una forma estable. Todo lo que viene después —en
 * este flujo y en los que llama— consume ESTA forma y no la de Meta, así que si
 * Meta cambia el formato del webhook se toca un solo archivo.
 *
 * Meta manda el mensaje anidado dentro de `messages[0]`, pero según la versión
 * del trigger a veces ya viene desanidado. Se contemplan las dos formas: es más
 * barato que descubrirlo en producción un domingo.
 */
const cfg = $('Configuración').first().json;
const raw = $input.first().json;

const mensaje = raw.messages?.[0] ?? raw.message ?? raw;
const contacto = raw.contacts?.[0] ?? {};

const soloDigitos = (t) => String(t ?? '').replace(/\D/g, '');

const telefono = soloDigitos(mensaje.from ?? contacto.wa_id);
const tipo = mensaje.type ?? 'desconocido';

// El texto puede venir como mensaje suelto o como epígrafe de una imagen.
const texto = (
  mensaje.text?.body ??
  mensaje.image?.caption ??
  mensaje.document?.caption ??
  ''
).trim();

// Sólo la imagen y el PDF cuentan como comprobante. Un audio o una ubicación no.
const adjunto =
  tipo === 'image' ? mensaje.image :
  tipo === 'document' ? mensaje.document :
  null;

const esDePia = telefono === soloDigitos(cfg.mpWhatsapp);

// El comando de confirmación. Se aceptan "OK 1234", "ok1234" y "OK  1234":
// Pía lo va a escribir con el pulgar, parada en cualquier lado.
const comando = texto.match(/^(ok|no)\s*(\d{4})$/i);

return [{
  json: {
    whatsapp: telefono,
    esDePia,
    tipo,
    texto,
    perfil: contacto.profile?.name ?? '',
    adjuntoId: adjunto?.id ?? '',
    adjuntoMime: adjunto?.mime_type ?? '',
    mensajeId: mensaje.id ?? '',
    recibidoEn: new Date().toISOString(),
    esComando: esDePia && comando !== null,
    comandoVerbo: comando ? comando[1].toUpperCase() : '',
    comandoCodigo: comando ? comando[2] : '',
  },
}];
